/**
 * Tests for scripts/lint-consumer-pairings.mjs (#1155).
 *
 * Two layers. A hand-built resolved set pins the rule semantics; the real set —
 * generated by `validate-themes.js --emit-resolved` from tokens/contrast-pairings.json —
 * carries the brikdesigns#676 positive control, so a dataset or cascade change that
 * stops the lint seeing the case turns this red instead of going quiet.
 */
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';

const SCRIPTS = dirname(fileURLToPath(import.meta.url));
const LINT = join(SCRIPTS, 'lint-consumer-pairings.mjs');
const GATE = join(SCRIPTS, 'validate-themes.js');
const PKG = JSON.parse(readFileSync(join(SCRIPTS, '..', 'package.json'), 'utf8'));

const row = (fg, bg, mode, fgValue, bgValue, thresholdType = 'AA') => ({
  fg, bg, mode, fgValue, bgValue, thresholdType, floor: thresholdType === 'AA-large' ? 3 : 4.5,
});
const FIXTURE = {
  thresholds: { AAA: 7, AA: 4.5, 'AA-large': 3 },
  colors: {
    light: { '--bds-grayscale-white': '#ffffff', '--bds-text-primary': '#333333' },
    dark: { '--bds-grayscale-white': '#ffffff', '--bds-grayscale-black': '#000000', '--bds-text-primary': '#f2f2f2' },
  },
  rows: [
    row('--bds-text-primary', '--bds-background-input', 'light', '#333333', '#ffffff', 'AAA'),
    row('--bds-text-primary', '--bds-background-input', 'dark', '#f2f2f2', '#1b1b1b', 'AAA'),
    row('--bds-text-muted', '--bds-background-input', 'dark', '#757575', '#1b1b1b', 'AA-large'),
  ],
};

/** @type {string[]} */
const dirs = [];
afterEach(() => {
  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

function plant(files, pairings = FIXTURE) {
  const root = mkdtempSync(join(tmpdir(), 'lint-consumer-pairings-'));
  dirs.push(root);
  writeFileSync(join(root, 'pairings.json'), JSON.stringify(pairings));
  for (const [rel, body] of Object.entries(files)) {
    const abs = join(root, rel);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, body, 'utf8');
  }
  return root;
}

function run(root, ...args) {
  try {
    const output = execFileSync('node', [LINT, 'src', '--pairings', join(root, 'pairings.json'), ...args], {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { status: 0, output };
  } catch (err) {
    return { status: err.status, output: `${err.stdout ?? ''}${err.stderr ?? ''}` };
  }
}

describe('pairing-fails', () => {
  it('fails an overridden bg that drops a validated pair below its floor', () => {
    const root = plant({ 'src/a.css': ':root[data-theme="dark"] {\n  --bds-background-input: #4f4f4f;\n}\n' });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('pairing-fails');
    expect(output).toContain('--bds-text-muted on --bds-background-input (dark)');
    expect(output).toContain('a.css:2');
  });

  it('uses the AA-large floor for an AA-large row, not 4.5', () => {
    // #757575 on #4f4f4f is ~1.9:1 -> fails 3:1. #757575 on #1b1b1b clears it.
    const ok = plant({ 'src/a.css': ':root[data-theme="dark"] { --bds-background-input: #111111; }\n' });
    expect(run(ok).status).toBe(0);
  });

  it('applies a base override to dark when no dark scope sets it', () => {
    const root = plant({ 'src/a.css': ':root { --bds-background-input: #4f4f4f; }\n' });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('(dark)');
  });

  it('lets a dark scope shadow the base override', () => {
    const root = plant({
      'src/a.css': ':root { --bds-background-input: #4f4f4f; }\n:root[data-theme="dark"] { --bds-background-input: #111111; }\n',
    });
    const { status, output } = run(root);
    expect(status).toBe(1); // light mode text-primary #333 on #4f4f4f still fails
    expect(output).toContain('(light)');
    expect(output).not.toContain('(dark)');
  });

  it('re-scores an overridden fg token against the BDS bg', () => {
    const root = plant({ 'src/a.css': ':root[data-theme="dark"] { --bds-text-primary: #222222; }\n' });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('--bds-text-primary on --bds-background-input (dark)');
  });

  it('resolves a var() override through the BDS resolved colors', () => {
    const root = plant({ 'src/a.css': ':root[data-theme="dark"] { --bds-background-input: var(--bds-grayscale-black); }\n' });
    expect(run(root).status).toBe(0);
    const bad = plant({ 'src/a.css': ':root[data-theme="dark"] { --bds-background-input: var(--bds-grayscale-white); }\n' });
    expect(run(bad).status).toBe(1);
  });

  it('is clean when no BDS token is overridden', () => {
    const root = plant({ 'src/a.css': '.card { color: red; }\n:root { --brand-x: #4f4f4f; }\n' });
    expect(run(root).status).toBe(0);
  });

  it('ignores a declaration that lives only in a comment', () => {
    const root = plant({ 'src/a.css': '/* --bds-background-input: #4f4f4f; */\n:root { color: red; }\n' });
    expect(run(root).status).toBe(0);
  });
});

describe('unvalidated-surface', () => {
  it('flags a raw color on a surface no pairing validates', () => {
    const root = plant({ 'src/a.css': ':root { --bds-surface-promo: #ff00aa; }\n' });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('unvalidated-surface');
  });

  it('does not flag a token reference', () => {
    const root = plant({ 'src/a.css': ':root { --bds-surface-promo: var(--bds-grayscale-white); }\n' });
    expect(run(root).status).toBe(0);
  });
});

describe('bds-lint-ignore', () => {
  const css = (marker) => `${marker}\n:root { --bds-surface-promo: #ff00aa; }\n`;

  it('honours a marker with a reason and an issue ref', () => {
    const root = plant({ 'src/a.css': css('/* bds-lint-ignore unvalidated-surface — campaign tint, no text on it #123 */') });
    expect(run(root).status).toBe(0);
  });

  it('rejects a marker with no issue ref', () => {
    const root = plant({ 'src/a.css': css('/* bds-lint-ignore unvalidated-surface — campaign tint */') });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('issue ref');
  });
});

describe('baseline that can only shrink', () => {
  const args = (root) => ['--baseline', join(root, 'baseline.json')];
  const bad = { 'src/a.css': ':root { --bds-surface-promo: #ff00aa; }\n' };

  it('accepts a baselined violation, fails a stale entry, refuses to grow', () => {
    const root = plant(bad);
    expect(run(root, ...args(root), '--write-baseline').status).toBe(0);
    expect(run(root, ...args(root)).status).toBe(0);
    writeFileSync(join(root, 'src/b.css'), ':root { --bds-surface-other: #00ffaa; }\n');
    expect(run(root, ...args(root)).status).toBe(1);
    expect(run(root, ...args(root), '--write-baseline').status).toBe(2);
    writeFileSync(join(root, 'src/a.css'), '.x { color: red; }\n');
    rmSync(join(root, 'src/b.css'));
    const stale = run(root, ...args(root));
    expect(stale.status).toBe(1);
    expect(stale.output).toContain('stale baseline');
  });
});

describe('invocation', () => {
  it('exits 2 when the resolved set is missing', () => {
    const root = plant({ 'src/a.css': '' });
    rmSync(join(root, 'pairings.json'));
    expect(run(root).status).toBe(2);
  });
});

describe('against the real contract (brikdesigns#676)', () => {
  let real;
  let realDir;
  beforeAll(() => {
    realDir = mkdtempSync(join(tmpdir(), 'lint-consumer-pairings-real-'));
    real = join(realDir, 'resolved.json');
    execFileSync('node', [GATE, '--emit-resolved', real], { stdio: 'ignore' });
  });
  afterAll(() => rmSync(realDir, { recursive: true, force: true }));

  const withReal = (files) => {
    const root = plant(files, JSON.parse(readFileSync(real, 'utf8')));
    return root;
  };

  it('POSITIVE CONTROL: #676 dark --bds-background-input #4f4f4f fails the lint', () => {
    const root = withReal({
      'src/globals.css': ':root[data-theme="dark"] {\n  --bds-background-input: #4f4f4f;\n  --bds-text-secondary: #bdbdbd;\n}\n',
    });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('pairing-fails');
    expect(output).toContain('--bds-background-input (dark)');
  });

  it('#1155 AC3: the secondary-text pairing is flagged below the AA floor (4.3599 -> 4.36; axe truncates it to 4.35)', () => {
    const root = withReal({
      'src/globals.css': ':root[data-theme="dark"] {\n  --bds-background-input: #4f4f4f;\n  --bds-text-secondary: #bdbdbd;\n}\n',
    });
    const { status, output } = run(root);
    expect(status).toBe(1);
    expect(output).toContain('--bds-text-secondary on --bds-background-input (dark)');
    expect(output).toContain('#bdbdbd on #4f4f4f = 4.36:1, below the AA floor 4.5:1');
  });

  it('CLEAN CONTROL: the BDS dark input fill via its own token passes', () => {
    const root = withReal({
      'src/globals.css': ':root[data-theme="dark"] {\n  --bds-background-input: var(--bds-color-grayscale-950);\n}\n',
    });
    expect(run(root).status).toBe(0);
  });
});

describe('package surface', () => {
  it('ships the pairings dataset, the lint, and its resolved set', () => {
    expect(PKG.files).toContain('tokens/contrast-pairings.json');
    expect(PKG.files).toContain('scripts/lint-consumer-pairings.mjs');
    expect(PKG.files).toContain('scripts/lib/wcag.mjs');
    expect(PKG.exports['./contrast-pairings.json']).toBe('./tokens/contrast-pairings.json');
    expect(PKG.exports['./contrast-pairings.resolved.json']).toBe('./dist/contrast-pairings.resolved.json');
    expect(PKG.bin['lint-consumer-pairings']).toBe('scripts/lint-consumer-pairings.mjs');
    expect(PKG.scripts['build:lib']).toContain('build:contrast-pairings');
  });
});
